/**
 * @version v1.0.2
 * @author Choi Sunki <iru@nate.com>
 * @description 특정 섹션 내의 이미지들이 모두 로드된 후 콜백을 실행하는 jQuery 플러그인
 *
 * @param {HTMLElement|NodeList} target - 이미지가 포함된 DOM 요소 또는 NodeList
 * @param {Object} opts - 옵션 객체
 * @param {Function} [opts.cb] - 모든 이미지 로드 후 실행할 콜백 함수
 * @param {boolean} [opts.cmessage=false] - 콘솔 메시지 출력 여부
 * 
 * @example
 * // jQuery 사용 시
 * $('.image-section').dload({
 *     cb: function() {
 *         console.log('모든 이미지가 로드되었습니다.');
 *     },
 *     cmessage: true
 * });
 *
 * @example
 * // 바닐라 JS 사용 시
 * dload(document.querySelector('.image-section'), {
 *     cb: function() {
 *         console.log('모든 이미지가 로드되었습니다.');
 *     },
 *     cmessage: true
 * });
 */
(function(g){function dload(t,o={}){const e=Object.assign({cmessage:!1},o),s=t instanceof NodeList||Array.isArray(t)?t:[t];s.forEach(t=>{const o=t.querySelectorAll("img");let s=0;const n=()=>{s++,e.cmessage&&console.log(`%c => Loading ${s}ea`,"background: #111; color: green; border-radius: 2px;"),s===o.length&&(e.cmessage&&console.log(`%c Load Complete ${s}ea`,"background: green; color: #111; border-radius: 2px; padding: 5px 10px;"),"function"==typeof e.cb&&e.cb())};o.forEach(t=>{const o=new Image;o.onload=n,o.onerror=n,o.src=t.getAttribute("src"),o.complete&&n()})})}"undefined"!=typeof jQuery&&"object"==typeof jQuery.fn&&(jQuery.fn.dload=function(t){return this.each(function(){dload(this,t)})}),g.dload=dload})(typeof window!=="undefined"?window:this);
